#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto doop=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    for(int k=0;k<n-2;k++){
        int val=k+1;
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
        if(pos==k) continue;
        // Step 1: bring val to position n-1
        if(pos!=n-1){
            // x=pos+1, y=n-1-pos: x+y=n, need <n. So use y=n-1-pos-1=n-2-pos if >0
            // Actually: set x=1, y=n-1-pos. Then C=p[pos+1..n-1], B=p[1..pos], A=p[0].
            // val at pos goes to B at position (n-1-pos)+(pos-1)=n-2. Not n-1.
            // x=1,y=n-1-pos: x+y=n-pos. Need <n, true since pos>0(pos>=k+1 or pos>=1 when k=0). 
            // Result: C+B+A. |C|=n-1-pos, |B|=pos-1+1-1=pos-1, |A|=1. val at pos -> in B at index (n-1-pos)+(pos-1)=n-2. Then A at n-1.
            // Hmm. Let me try: x=pos-k, y=n-1-pos. x+y=n-1-k. Need <n: true. Need x>0: pos>k true. Need y>0: pos<n-1 true.
            // C=p[n-(n-1-pos)..n-1]=p[pos+1..n-1]. B=p[pos-k..pos]. A=p[0..pos-k-1].
            // val at pos is at B[k]=start of B + k? B starts at |C|=n-1-pos. val in B at index (n-1-pos)+k.
            // We want n-1. (n-1-pos)+k=n-1 => k=pos. Only if pos=k which we excluded. 
            // Just move to n-1: x=pos+1-(pos==n-2?0:0), try x=pos+1,y=n-pos-2 if valid
            int x=pos+1, y=n-pos-2;
            if(y>0 && x>0 && x+y<n) doop(x,y);
            // find again
            for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
            if(pos!=n-1 && pos!=k){
                x=1; y=n-1-pos;
                if(y>0 && x>0 && x+y<n) doop(x,y);
                for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
            }
        }
        if(pos==k) continue;
        if(pos==n-1 && k+1>0 && 1>0 && k+1+1<n){
            // x=k+1,y=1: C=p[n-1], B=p[k+1..n-2], A=p[0..k]. Result: [val, B, A]. val at pos 0. Need pos k.
            // x=1,y=n-1-k: C=p[k+1..n-1](includes val at n-1), B=p[1..k], A=p[0]. val at end of C = pos n-1-k-1. Not k.
            int x2=n-1-k, y2=k; // C=p[n-k..n-1] len k, B=p[n-1-k..n-k-1]=empty if..., A=p[0..n-2-k]
            if(y2>0 && x2>0 && x2+y2<n) doop(x2,y2);
            for(int i=k;i<n;i++) if(p[i]==val){pos=i;break;}
        }
        if(pos==k) continue;
        // fallback brute: try all valid (x,y)
        for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
            // simulate
            vector<int> tp;
            for(int i=n-y;i<n;i++) tp.push_back(p[i]);
            for(int i=x;i<n-y;i++) tp.push_back(p[i]);
            for(int i=0;i<x;i++) tp.push_back(p[i]);
            if(tp[k]==val){doop(x,y);break;}
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
